/* ========================================================================
   ONLINE-SPIL: FORBINDELSEN TIL RELAYEN (læsbar kode)
   roomSocket åbner en WebSocket til relayen (adressen står i indstillinger.js).
   RelayHost = værtens side, RelayGuest = deltagerens side. Ændres beskederne her,
   skal relay/src/index.js ændres tilsvarende, og relayen deployes først.
   ======================================================================== */
function roomSocket(query) {
  return new WebSocket(window.EPOKE_RELAY_URL + "?" + query);
}
function keepAlive(ws) {
  const t = setInterval(() => {if (ws.readyState === 1) ws.send("ping"); else if (ws.readyState > 1) clearInterval(t);}, 25000);
}
class RelayHost {
  constructor(hooks) {
    this.clients = new Set();
    this.socket = roomSocket("role=host");
    keepAlive(this.socket);
    this.socket.onopen = () => this.socket.send(JSON.stringify({role:"host"}));
    this.socket.onmessage = ({data}) => {
      if (data === "pong") return;
      const msg = JSON.parse(data);
      if (msg.type === "ready") {this.code = msg.code; hooks.onOpen(msg.code);}
      if (msg.type === "hello") {this.clients.add(msg.id); hooks.onHello(msg.id,msg.name,msg.avatar);}
      if (msg.type === "action") hooks.onAction(msg.id,msg.act);
      if (msg.type === "leave") {this.clients.delete(msg.id); hooks.onLeave(msg.id);}
    };
    this.socket.onclose = () => {if (!this.closed) {hooks.onError({type:"forbindelse afbrudt"});pe("Forbindelsen til spilserveren blev afbrudt.");}};
  }
  send(id,value,kick=false) {if(this.socket.readyState===1)this.socket.send(JSON.stringify({id,value,kick}));}
  broadcast(build) {for(const id of this.clients)this.send(id,build(id));}
  kick(id,value) {this.send(id,value,true);}
  close() {this.closed=true;this.socket.close();}
}
class RelayGuest {
  constructor(code,hello,hooks) {
    this.code=code; this.hello=hello; this.hooks=hooks;
    const storageKey="timeline3-relay-"+code;
    this.key=sessionStorage.getItem(storageKey)||crypto.randomUUID();
    sessionStorage.setItem(storageKey,this.key);

    this.connect();
  }
  connect() {
    const ws=this.socket=roomSocket("code="+encodeURIComponent(this.code.toUpperCase()));
    keepAlive(ws);
    ws.onopen=()=>ws.send(JSON.stringify({...this.hello,role:"guest",code:this.code,key:this.key}));
    ws.onmessage=({data})=>{
      if(data==="pong")return;
      const msg=JSON.parse(data);
      if(msg.type==="ready"){re=msg.id;this.tries=0;this.hooks.onStatus("open");}
      if(msg.type==="unavailable"){this.closed=true;this.hooks.onStatus("notfound");}
      if(msg.type==="message"){if(["full","kicked"].includes(msg.value.t))this.closed=true;this.hooks.onMsg(msg.value);}
    };
    ws.onclose=()=>{if(!this.closed){this.hooks.onStatus("lost");this.tries=(this.tries||0)+1;if(this.tries<8)this.timer=setTimeout(()=>this.connect(),1500);}};
  }
  act(act){if(this.socket.readyState===1)this.socket.send(JSON.stringify({act}));}
  close(){this.closed=true;clearTimeout(this.timer);this.socket.close();}
}


