  const head=last.ok?(last.exact?'Præcist årstal!':'Rigtigt!'):'Forkert';
  const help=discard?(state.settings.mode==="infinite"?"Tryk på et kort på hånden for at fjerne det og få et nyt i stedet.":"Vælg et kort fra hånden at kassere, eller behold det."):"";
