/* ========================================================================
   MUSIK
   Forsiden: "Fiddle De Dee" spiller én gang og fader ind (fortsætter i menuerne).
   Under spillet: "The Old Tower Inn" i løkke. Et kortsæt med egen musik (music i
   sætfilen, fx jul) erstatter den under spillet. Når forsidemusikken er færdig,
   spiller The Old Tower Inn også i menuerne. Styrker står i indstillinger.js.
   ======================================================================== */
const MUSIC_HOME="music/fiddle-de-dee.mp3",MUSIC_GAME="music/the-old-tower-inn.mp3";
const homeAudio=new Audio(MUSIC_HOME),gameAudio=new Audio(MUSIC_GAME);homeAudio.loop=false;homeAudio.volume=0;gameAudio.loop=true;gameAudio.volume=0;
let musicBlocked=false,musicFade=null,musicStarted=false,homeDone=false,homeFade=null,fadingOut=false;
const GAME_VOL=INDST.musikStyrke??.3,FADE_IN_MS=INDST.musikIndfadningMs??4000,FADE_IN_FROM=INDST.musikStartStyrke??.3;
const HOME_VOL=INDST.forsideMusikStyrke??.23,HOME_FADE_IN_MS=INDST.forsideMusikIndfadningMs??8000,HOME_FADE_FROM=INDST.forsideMusikStartStyrke??.4,
  HOME_FADE_OUT_MS=INDST.forsideMusikUdfadningMs??2500,HOME_START=INDST.forsideMusikStartSek??34.2;
function fadeInGame(){clearInterval(musicFade);const t0=Date.now();gameAudio.volume=GAME_VOL*FADE_IN_FROM;
  musicFade=setInterval(()=>{const f=Math.min(1,(Date.now()-t0)/FADE_IN_MS);gameAudio.volume=GAME_VOL*(FADE_IN_FROM+(1-FADE_IN_FROM)*f);if(f>=1)clearInterval(musicFade)},50)}
// Forsidemusikken: start (med indfadning) og udfadning.
function startHome(){homeDone=true;homeAudio.volume=HOME_VOL*HOME_FADE_FROM;
  const go=()=>{try{homeAudio.currentTime=HOME_START}catch(e){}homeAudio.play().then(()=>{clearInterval(homeFade);const t0=Date.now();
    homeFade=setInterval(()=>{const f=Math.min(1,(Date.now()-t0)/HOME_FADE_IN_MS);homeAudio.volume=HOME_VOL*(HOME_FADE_FROM+(1-HOME_FADE_FROM)*f);if(f>=1)clearInterval(homeFade)},50)
  }).catch(()=>{homeDone=false;musicBlocked=true})};
  homeAudio.readyState>=1?go():homeAudio.addEventListener("loadedmetadata",go,{once:true})}
function fadeOutHome(done){clearInterval(homeFade);const from=homeAudio.volume,t0=Date.now();
  homeFade=setInterval(()=>{const f=Math.min(1,(Date.now()-t0)/HOME_FADE_OUT_MS);homeAudio.volume=Math.max(0,from*(1-f));if(f>=1){clearInterval(homeFade);done()}},50)}
function playCur(cur){
  for(const oth of [gameAudio,...TimelineSets.allMusic()])if(oth!==cur&&!oth.paused){oth.pause();if(oth!==gameAudio)oth.currentTime=0}
  if(cur.paused){const first=cur===gameAudio&&!musicStarted;if(cur!==gameAudio)cur.volume=GAME_VOL;else if(!first&&!musicFade)cur.volume=GAME_VOL;
    cur.play().then(()=>{if(first){musicStarted=true;fadeInGame()}}).catch(()=>{musicBlocked=true})}}
function musicTick(){
  if(!ee||musicBlocked){clearInterval(musicFade);clearInterval(homeFade);fadingOut=false;homeAudio.pause();gameAudio.pause();TimelineSets.pauseAllMusic();return}
  const inGame=!!document.querySelector("#scr-game.show"),onHome=!!document.querySelector("#scr-home.show");
  if(inGame){
    homeDone=false;
    // Forsidemusikken fader ud, før spillets musik starter.
    if(!homeAudio.paused){if(!fadingOut){fadingOut=true;fadeOutHome(()=>{homeAudio.pause();fadingOut=false;musicTick()})}return}
    playCur(TimelineSets.musicFor(k&&k.settings&&k.settings.set)||gameAudio);return}
  // Menuer: forsidemusikken, hvis den spiller eller skal starte; ellers den almindelige musik.
  if(onHome&&!homeDone&&homeAudio.paused){for(const a of [gameAudio,...TimelineSets.allMusic()])if(!a.paused)a.pause();startHome();return}
  if(!homeAudio.paused){for(const a of [gameAudio,...TimelineSets.allMusic()])if(!a.paused)a.pause();return}
  playCur(gameAudio);
}
const unblockMusic=()=>{if(musicBlocked){musicBlocked=false;musicTick()}};
["pointerdown","keydown"].forEach(ev=>document.addEventListener(ev,unblockMusic,true));
const homeSoundBtn=document.getElementById("home-sound");
function syncHomeSound(){if(!homeSoundBtn)return;homeSoundBtn.classList.toggle("on",ee);homeSoundBtn.setAttribute("aria-pressed",String(ee));homeSoundBtn.title=ee?"Slå lyden fra":"Slå lyden til"}
if(homeSoundBtn)homeSoundBtn.onclick=()=>{ee=!ee;E.set("sound",ee);u("#btn-sound").textContent=ee?"\u{1F50A}":"\u{1F507}";if(ee){homeDone=false;musicBlocked=false;A("tick")}syncHomeSound();musicTick()};
setInterval(()=>{syncHomeSound();musicTick()},400);syncHomeSound();musicTick();

